class OptimizeRecoveryTest : public ::testing::Test {
 protected:
  void SetUp() override {
    zvec::test_util::RemoveTestPath("./optimize_recovery_test_db");
    ASSERT_NO_THROW(optimizer_bin_ = LocateOptimizeGenerator());
