      auto drop_index_task = std::get<DropScalarIndexTask>(task_info);
      s = drop_index_task.input_segment_->reload_scalar_index(
          *new_schema, drop_index_task.output_segment_meta_,
          drop_index_task.output_scalar_indexer_);
